// WeeklyPlan defines model for WeeklyPlan.
type WeeklyPlan struct {
	// Fallback True when the rule-based plan was used because the AI call failed.
	Fallback    bool      `json:"fallback"`
	GeneratedAt time.Time `json:"generatedAt"`

	// Intro One or two warm sentences that open the note.
	Intro    string              `json:"intro"`
	MemberId openapi_types.UUID  `json:"memberId"`
	Sections []WeeklyPlanSection `json:"sections"`
}

// WeeklyPlanPoint defines model for WeeklyPlanPoint.
type WeeklyPlanPoint struct {
	// Reason The data behind the point, for example "You slept 5.5 hours on average this week."
	Reason string `json:"reason"`

	// RuleId The rule plan item this point comes from, when it has one.
	RuleId *string `json:"ruleId,omitempty"`
	Source *Source `json:"source,omitempty"`

	// Text What to do, in one or two plain sentences. Never a diagnosis. Any medical point must carry a source.
	Text string `json:"text"`
}

// WeeklyPlanSection defines model for WeeklyPlanSection.
type WeeklyPlanSection struct {
	Points []WeeklyPlanPoint `json:"points"`

	// Title Example: For you
	Title string `json:"title"`
}

// WeeklyRead defines model for WeeklyRead.
type WeeklyRead struct {
	Body string `json:"body"`

	// EndsOn Last day. Absent for the planning read, pregnancy week 40 (it lasts until the birth) and the last year, which stays open.
	EndsOn *openapi_types.Date `json:"endsOn,omitempty"`

	// Id Stable key, the kind and its number, for example pregnancy_week-12.
	//
	// Example: baby_week-4
	Id   string         `json:"id"`
	Kind WeeklyReadKind `json:"kind"`

	// Label Example: Week 5
	Label string `json:"label"`

	// N Pregnancy week, week of life (0 is the first 7 days), completed months or completed years.
	N       int      `json:"n"`
	Sources []Source `json:"sources"`

	// StartsOn First day of the week, month or year on the family's calendar. Absent for the planning read.
	StartsOn *openapi_types.Date `json:"startsOn,omitempty"`
	Title    string              `json:"title"`
}

// WeeklyReadKind defines model for WeeklyReadKind.
type WeeklyReadKind string

// WeeklyReadList defines model for WeeklyReadList.
type WeeklyReadList struct {
	// Current Index of today's read in items.
	Current int `json:"current"`

	// Items The family's whole track in order (oldest first, unlike other lists, so it can be browsed week by week).
	Items []WeeklyRead `json:"items"`
}

